#define CG3_BOUNDINGBOX2_CPP "bounding_box2.cpp"
#include CG3_BOUNDINGBOX2_CPP
#undef CG3_BOUNDINGBOX2_CPP
#endif //CG3_STATIC

#endif // CG3_BOUNDINGBOX2_H

