// Assume Point2d and BoundingBox2 are defined as follows:
class Point2d {
public:
    Point2d(double x = 0.0, double y = 0.0) : xCoord(x), yCoord(y) {}
    double x() const { return xCoord; }
    double y() const { return yCoord; }
    Point2d min(const Point2d& other) const {
        return Point2d(std::min(xCoord, other.xCoord), std::min(yCoord, other.yCoord));
    }
    Point2d max(const Point2d& other) const {
        return Point2d(std::max(xCoord, other.xCoord), std::max(yCoord, other.yCoord));
    }
private:
    double xCoord, yCoord;
};

class BoundingBox2 {
public:
    BoundingBox2() : minCoord(Point2d(std::numeric_limits<double>::max(), std::numeric_limits<double>::max())),
                    maxCoord(Point2d(std::numeric_limits<double>::lowest(), std::numeric_limits<double>::lowest())) {}
    BoundingBox2(const Point2d& min, const Point2d& max) : minCoord(min), maxCoord(max) {}
    const Point2d& min() const { return minCoord; }
    const Point2d& max() const { return maxCoord; }
    Point2d& min() { return minCoord; }
    Point2d& max() { return maxCoord; }
    void setMin(const Point2d& p) { minCoord = p; }
    void setMax(const Point2d& p) { maxCoord = p; }
private:
    Point2d minCoord, maxCoord;
};

BoundingBox2 minimumBoundingBox2D(const std::vector<Point2d>& points) {
    if (points.empty()) {
        return BoundingBox2();
    }
    Point2d minCoord = points[0];
    Point2d maxCoord = points[0];
    for (const Point2d& p : points) {
        minCoord = minCoord.min(p);
        maxCoord = maxCoord.max(p);
    }
    return BoundingBox2(minCoord, maxCoord);
}

